// Python's `print` / `sys.stderr.write` mapped onto Node's streams.
//
// Nothing here calls `process.exit()`. The entry point sets `process.exitCode`
// and returns instead, so Node always drains stdout/stderr before terminating --
// `process.exit()` truncates pipes because those streams are asynchronous.

export function writeStdout(text) {
  process.stdout.write(text);
}

export function writeStderr(text) {
  process.stderr.write(text);
}

/** `print(value)` -- the text followed by a single newline. */
export function print(text) {
  writeStdout(`${text}\n`);
}

