// Bech32 alphabet and the constants that bound a well-formed string.

export const CHARSET = 'qpzry9x8gf2tvdw0s3jn54khce6mua7l';

export const GENERATOR = [0x3b6a57b2, 0x26508e6d, 0x1ea119fa, 0x3d4233dd, 0x2a1462b3];

/** Trailing data symbols that carry the BCH checksum. */
export const CHECKSUM_LENGTH = 6;

/**
 * BIP-173 caps the human-readable part at 83 characters. The reference module
 * enforces that bound and imposes no 90-character limit on the string as a
 * whole: an 83-character HRP with a 40-byte witness program (155 characters
 * total) decodes, while an 84-character HRP is rejected at any total length.
 */
export const MAX_HRP_LENGTH = 83;

export function charsetIndex(char) {
  return CHARSET.indexOf(char);
}

export function isCharsetChar(char) {
  return CHARSET.includes(char);
}

