// The BCH checksum over GF(32) that bech32 strings carry.
//
// Every intermediate stays inside 30 bits -- `chk` is masked to 25 bits before
// being shifted left by 5, and the generator constants are all below 2**30 --
// so JavaScript's 32-bit bitwise operators are exact here and agree with
// Python's arbitrary-precision integers bit for bit.

import { CHECKSUM_LENGTH, GENERATOR } from './charset.mjs';
import { codePoints } from '../python/text.mjs';

export function bech32Polymod(values) {
  let chk = 1;
  for (const value of values) {
    const top = chk >> 25;
    chk = ((chk & 0x1ffffff) << 5) ^ value;
    for (let i = 0; i < GENERATOR.length; i += 1) {
      if ((top >> i) & 1) {
        chk ^= GENERATOR[i];
      }
    }
  }
  return chk;
}

/** High bits of the HRP, a zero separator, then the low bits. */
export function bech32HrpExpand(hrp) {
  const points = codePoints(hrp);
  return [...points.map((point) => point >> 5), 0, ...points.map((point) => point & 31)];
}

export function bech32VerifyChecksum(hrp, data) {
  return bech32Polymod([...bech32HrpExpand(hrp), ...data]) === 1;
}

export function bech32CreateChecksum(hrp, data) {
  const values = [...bech32HrpExpand(hrp), ...data, ...new Array(CHECKSUM_LENGTH).fill(0)];
  const polymod = bech32Polymod(values) ^ 1;
  const checksum = [];
  for (let i = 0; i < CHECKSUM_LENGTH; i += 1) {
    checksum.push((polymod >> (5 * (5 - i))) & 31);
  }
  return checksum;
}

