// Segwit address layer -- `bech32.decode` / `bech32.encode`.
//
// This mirrors the BIP-173-only behaviour of the reference module: a witness
// version of 1..16 is accepted with an ordinary bech32 checksum, and bech32m
// (BIP-350) strings are rejected outright.

import { bech32Decode, bech32Encode } from './codec.mjs';
import { convertbits } from './convert.mjs';

export const MIN_PROGRAM_LENGTH = 2;
export const MAX_PROGRAM_LENGTH = 40;
export const MAX_WITNESS_VERSION = 16;

function failure() {
  return [null, null];
}

/**
 * Decode a segwit address into `[witnessVersion, witnessProgram]`, where the
 * program is a plain array of byte values, or `[null, null]` on any failure.
 *
 * The program-length check deliberately precedes the `data[0]` read: for a
 * checksum-only string the payload is empty, the conversion yields `[]`, and the
 * length test bails out before the witness version would be indexed.
 */
export function decode(hrp, addr) {
  const [hrpGot, data] = bech32Decode(addr);
  if (hrpGot !== hrp) {
    return failure();
  }

  const decoded = convertbits(data.slice(1), 5, 8, false);
  if (
    decoded === null ||
    decoded.length < MIN_PROGRAM_LENGTH ||
    decoded.length > MAX_PROGRAM_LENGTH
  ) {
    return failure();
  }
  if (data[0] > MAX_WITNESS_VERSION) {
    return failure();
  }
  if (data[0] === 0 && decoded.length !== 20 && decoded.length !== 32) {
    return failure();
  }
  return [data[0], decoded];
}

/** Encode a segwit address, or `null` when the result would not round-trip. */
export function encode(hrp, witver, witprog) {
  const addr = bech32Encode(hrp, [witver, ...convertbits(witprog, 8, 5)]);
  const [version, program] = decode(hrp, addr);
  if (version === null && program === null) {
    return null;
  }
  return addr;
}

