input.content:
// A faithful port of the slice of Python's `argparse.ArgumentParser` that this
// CLI exercises: two required value-taking long options plus the automatic
// `-h/--help`, and no positionals.
//
// The token-classification and consumption algorithm follows CPython's
// `_parse_known_args` closely, because its quirks are observable:
//   * a required-argument error is raised before unrecognised arguments are
//     reported, so a missing `--a` wins over trailing junk;
//   * `-5` and `-1.5` are values (they look like negative numbers) while `-x`
//     and `-5x` are option strings, so `--b -x` fails with "expected one
//     argument" rather than storing "-x";
//   * `--h`, `--he` and `--hel` all resolve to `--help` by unique-prefix match;
//   * `--` is a separator that is itself left over as an unrecognised argument,
//     since no positional action is declared to absorb it.

import { basename } from 'node:path';

import { HELP, STORE, Action, destFromOptionStrings, makeHelpAction } from './actions.mjs';
import { ArgumentError, ParserExit } from './errors.mjs';
import { formatHelp, formatUsage } from './formatter.mjs';
import { pyRepr } from '../python/repr.mjs';

const PREFIX_CHARS = '-';

/** argparse's own "this token is a negative number, not an option" test. */
const NEGATIVE_NUMBER = /^-\d+$|^-\d*\.\d+$/;

/** argparse's default `prog`: `os.path.basename(sys.argv[0])`. */
export function defaultProg() {
  const script = process.argv[1];
  return script === undefined ? '' : basename(script);
}

export class ArgumentParser {
  constructor({ prog = defaultProg(), addHelp = true } = {}) {
    this.prog = prog;
    this.actions = [];
    this.optionStringActions = new Map();
    if (addHelp) {
      this.addAction(makeHelpAction());
    }
  }

  addAction(action) {
    this.actions.push(action);
    for (const optionString of action.optionStrings) {
      this.optionStringActions.set(optionString, action);
    }
    return action;
  }

  addArgument(flags, options = {}) {
    const optionStrings = Array.isArray(flags) ? flags : [flags];
    return this.addAction(
      new Action({
        optionStrings,
        dest: options.dest ?? destFromOptionStrings(optionStrings),
        kind: STORE,
        nargs: null,
        required: options.required === true,
        metavar: options.metavar ?? null,
        help: options.help ?? '',
        type: options.type ?? null,
      }),
    );
  }

  formatUsage() {
    return formatUsage(this.prog, this.actions);
  }

  formatHelp() {
    return formatHelp(this.prog, this.actions);
  }

  /** Print usage plus a message on stderr and terminate with status 2. */
  error(message) {
    throw new ParserExit(2, {
      stderr: `${this.formatUsage()}${this.prog}: error: ${message}\n`,
    });
  }

  parseArgs(argv) {
    const [namespace, extras] = this.parseKnownArgs(argv);
    if (extras.length > 0) {
      this.error(`unrecognized arguments: ${extras.join(' ')}`);
    }
    return namespace;
  }

  parseKnownArgs(argv) {
    try {
      return this.parseKnownArgsUnchecked(argv);
    } catch (error) {
      if (error instanceof ArgumentError) {
        this.error(error.message);
      }
      throw error;
    }
  }

  parseKnownArgsUnchecked(argv) {
    const namespace = {};
    for (const action of this.actions) {
      if (action.kind === STORE) {
        namespace[action.dest] = null;
      }
    }

    // Classify every token up front: 'O' for something that looks like an
    // option, 'A' for a value, '-' for the `--` separator. Option matching then
    // works against this pattern rather than against the raw strings, which is
    // what makes `--b -- value` fail instead of storing "--".
    const pattern = [];
    const optionTuples = new Map();
    let index = 0;
    while (index < argv.length) {
      if (argv[index] === '--') {
        pattern.push('-');
        index += 1;
        while (index < argv.length) {
          pattern.push('A');
          index += 1;
        }
        break;
      }
      const tuple = this.parseOptional(argv[index]);
      if (tuple === null) {
        pattern.push('A');
      } else {
        optionTuples.set(index, tuple);
        pattern.push('O');
      }
      index += 1;
    }

    const extras = [];
    const seen = new Set();
    const context = { argv, pattern, optionTuples, extras, seen, namespace };

    const optionIndices = [...optionTuples.keys()].sort((left, right) => left - right);
    const maxOptionIndex = optionIndices.length === 0 ? -1 : optionIndices[optionIndices.length - 1];
    let start = 0;
    while (start <= maxOptionIndex) {
      const next = optionIndices.find((candidate) => candidate >= start);
      if (next === undefined) {
        break;
      }
      if (start !== next) {
        // No positional action is declared, so nothing before the next option
        // can be consumed -- it all becomes unrecognised.
        extras.push(...argv.slice(start, next));
        start = next;
      }
      start = this.consumeOptional(start, context);
    }
    extras.push(...argv.slice(start));

    const missing = this.actions
      .filter((action) => action.required && !seen.has(action))
      .map((action) => action.optionStrings.join('/'));
    if (missing.length > 0) {
      this.error(`the following arguments are required: ${missing.join(', ')}`);
    }

    return [namespace, extras];
  }

  consumeOptional(startIndex, context) {
    const { argv, pattern, optionTuples, extras, seen, namespace } = context;
    let { action, optionString, explicitArg } = optionTuples.get(startIndex);
    const actionTuples = [];
    let stop = startIndex + 1;

    for (;;) {
      if (action === null) {
        // An option string no action claims: report the whole token verbatim.
        extras.push(argv[startIndex]);
        return startIndex + 1;
      }

      if (explicitArg !== null) {
        const argCount = this.matchArgument(action, 'A');
        if (argCount === 0 && !PREFIX_CHARS.includes(optionString[1]) && explicitArg !== '') {
          // A single-dash flag with a tail: `-hz` means `-h` then `-z`.
          actionTuples.push([action, []]);
          const prefix = optionString[0];
          optionString = prefix + explicitArg[0];
          const nextAction = this.optionStringActions.get(optionString);
          if (nextAction === undefined) {
            extras.push(prefix + explicitArg);
            stop = startIndex + 1;
            break;
          }
          action = nextAction;
          explicitArg = explicitArg.slice(1);
          if (explicitArg === '') {
            explicitArg = null;
          } else if (explicitArg[0] === '=') {
            explicitArg = explicitArg.slice(1);
          }
        } else if (argCount === 1) {
          stop = startIndex + 1;
          actionTuples.push([action, [explicitArg]]);
          break;
        } else {
          throw new ArgumentError(action, `ignored explicit argument ${pyRepr(explicitArg)}`);
        }
      } else {
        const valueStart = startIndex + 1;
        const argCount = this.matchArgument(action, pattern.slice(valueStart).join(''));
        stop = valueStart + argCount;
        actionTuples.push([action, argv.slice(valueStart, stop)]);
        break;
      }
    }

    for (const [chosen, values] of actionTuples) {
      seen.add(chosen);
      this.takeAction(chosen, values, namespace);
    }
    return stop;
  }

  /** How many following tokens this action consumes, or a parse error. */
  matchArgument(action, patternText) {
    if (action.nargs === 0) {
      return 0;
    }
    if (patternText.startsWith('A')) {
      return 1;
    }
    throw new ArgumentError(action, 'expected one argument');
  }

  takeAction(action, values, namespace) {
    if (action.kind === HELP) {
      throw new ParserExit(0, { stdout: this.formatHelp() });
    }
    const [value] = values;
    namespace[action.dest] = action.type === null ? value : action.type(value);
  }

  hasNegativeNumberOptionals() {
    for (const optionString of this.optionStringActions.keys()) {
      if (NEGATIVE_NUMBER.test(optionString)) {
        return true;
      }
    }
    return false;
  }

  /**
   * Decide whether a token is an option. Returns `null` when it should be
   * treated as a value, otherwise `{action, optionString, explicitArg}` where a
   * `null` action means "looks like an option, but nothing matches".
   */
  parseOptional(argString) {
    if (argString === '') {
      return null;
    }
    if (!PREFIX_CHARS.includes(argString[0])) {
      return null;
    }
    const exact = this.optionStringActions.get(argString);
    if (exact !== undefined) {
      return { action: exact, optionString: argString, explicitArg: null };
    }
    if (argString.length === 1) {
      // A lone '-' is a value.
      return null;
    }

    const equals = argString.indexOf('=');
    if (equals !== -1) {
      const optionString = argString.slice(0, equals);
      const action = this.optionStringActions.get(optionString);
      if (action !== undefined) {
        return { action, optionString, explicitArg: argString.slice(equals + 1) };
      }
    }

    const tuples = this.getOptionTuples(argString);
    if (tuples.length > 1) {
      const options = tuples.map((tuple) => tuple.optionString).join(', ');
      this.error(`ambiguous option: ${argString} could match ${options}`);
    }
    if (tuples.length === 1) {
      return tuples[0];
    }

    if (NEGATIVE_NUMBER.test(argString) && !this.hasNegativeNumberOptionals()) {
      return null;
    }
    if (argString.includes(' ')) {
      return null;
    }
    return { action: null, optionString: argString, explicitArg: null };
  }

  /** Every option string this abbreviation could stand for. */
  getOptionTuples(argString) {
    const tuples = [];

    if (PREFIX_CHARS.includes(argString[0]) && PREFIX_CHARS.includes(argString[1])) {
      // Long options must be separated from their value by '=' or a space.
      const equals = argString.indexOf('=');
      const optionPrefix = equals === -1 ? argString : argString.slice(0, equals);
      const explicitArg = equals === -1 ? null : argString.slice(equals + 1);
      for (const [optionString, action] of this.optionStringActions) {
        if (optionString.startsWith(optionPrefix)) {
          tuples.push({ action, optionString, explicitArg });
        }
      }
      return tuples;
    }

    // Single-character options may be concatenated with their value.
    const shortOptionPrefix = argString.slice(0, 2);
    const shortExplicitArg = argString.slice(2);
    for (const [optionString, action] of this.optionStringActions) {
      if (optionString === shortOptionPrefix) {
        tuples.push({ action, optionString, explicitArg: shortExplicitArg });
      } else if (optionString.startsWith(argString)) {
        tuples.push({ action, optionString, explicitArg: null });
      }
    }
    return tuples;
  }
}

export { ArgumentError, ParserExit };

