import { segwitEncode, bech32Encode, CHARSET } from '/tmp/probe/gen.mjs';
import { writeFileSync } from 'node:fs';

const cases = [];
const add = (a, b) => cases.push(['--a', a, '--b', b]);
// deterministic PRNG so runs are reproducible
let seed = 20260807;
const rnd = (n) => { seed = (seed * 1103515245 + 12345) & 0x7fffffff; return seed % n; };

const HRPS = ['bc', 'tb', 'ltc', 'test', 'a', 'bcrt', '123', 'x1y'];

// v0: 20 and 32 byte programs, low-byte and high-byte variants
for (const hrp of HRPS) {
  for (const len of [20, 32]) {
    for (const kind of ['low', 'high', 'zero', 'max31', 'one32', 'mixed']) {
      const prog = Array.from({ length: len }, (_, i) => {
        if (kind === 'low') return i % 32;
        if (kind === 'high') return (i * 7 + 40) % 256;
        if (kind === 'zero') return 0;
        if (kind === 'max31') return 31;
        if (kind === 'one32') return i === len - 1 ? 32 : 5;
        return rnd(256);
      });
      const addr = segwitEncode(hrp, 0, prog);
      if (addr) { add(hrp, addr); add(hrp.toUpperCase(), addr.toUpperCase()); add(hrp, addr.toUpperCase()); }
    }
  }
}
// v1..v16, every program length 2..40, boundary byte values
for (let wv = 1; wv <= 16; wv += 1) {
  for (let len = 2; len <= 40; len += 1) {
    for (const cap of [31, 32, 255]) {
      const prog = Array.from({ length: len }, (_, i) => (i === 0 ? cap : (i * 3) % (cap + 1)));
      const addr = segwitEncode('bc', wv, prog);
      if (addr) add('bc', addr);
    }
  }
}
// invalid witness versions and lengths via raw 5-bit payloads
for (let wv = 17; wv <= 31; wv += 1) {
  for (const n of [4, 32, 52, 64]) {
    add('bc', bech32Encode('bc', [wv, ...Array.from({ length: n }, (_, i) => i % 32)]));
  }
}
for (let n = 0; n <= 70; n += 1) {
  add('bc', bech32Encode('bc', [0, ...Array.from({ length: n }, (_, i) => (i * 5) % 32)]));
  add('bc', bech32Encode('bc', [1, ...Array.from({ length: n }, (_, i) => (i * 5) % 32)]));
}
// hrp length sweep with two program sizes
for (let n = 1; n <= 95; n += 1) {
  const hrp = 'q'.repeat(n);
  for (const prog of [[1, 2], Array.from({ length: 40 }, (_, i) => i % 32)]) {
    const addr = segwitEncode(hrp, 1, prog);
    if (addr) add(hrp, addr);
  }
}
// every printable ascii code point as a single-char hrp
for (let cp = 33; cp <= 126; cp += 1) {
  const hrp = String.fromCharCode(cp);
  const addr = segwitEncode(hrp, 1, [1, 2]);
  if (addr) { add(hrp, addr); add(hrp, addr.toUpperCase()); add(hrp.toUpperCase(), addr); }
}
// checksum tampering + case flipping on a base address
const base = segwitEncode('bc', 1, [1, 2, 3, 4, 5]);
for (let i = 0; i < base.length; i += 1) {
  for (const ch of ['q', 'p', '1', 'b', 'i', 'o', '0', 'l', ' ', '\t', 'A', '~', 'é', '\u{1f600}']) {
    add('bc', base.slice(0, i) + ch + base.slice(i + 1));
  }
  add('bc', base.slice(0, i) + base.slice(i + 1));                              // delete
  add('bc', base.slice(0, i) + base[i] + base.slice(i));                        // duplicate
  if (i + 1 < base.length) add('bc', base.slice(0, i) + base[i + 1] + base[i] + base.slice(i + 2)); // swap
  const flipped = base[i] === base[i].toUpperCase() ? base[i].toLowerCase() : base[i].toUpperCase();
  add('bc', base.slice(0, i) + flipped + base.slice(i + 1));                    // single-char case flip
}
// separator edge cases
for (const b of ['', '1', '11', 'bc', 'bc1', 'bc11', 'bc1q', 'bc1qqqqq', 'bc1qqqqqq', '1' + base, base + '1', base.replace('1', ''), 'bc1' + base]) add('bc', b);
// hrp mismatch shapes
for (const a of ['', 'b', 'bc', 'bcc', 'BC', 'Bc', ' bc', 'bc ', 'tb', 'é']) add(a, base);
// oversized inputs
add('bc', 'bc1' + 'q'.repeat(1200));
add('q'.repeat(1200), base);
add('bc', CHARSET.repeat(40));

writeFileSync('/tmp/corpus/orchestrator.json', JSON.stringify(cases));
console.log('cases', cases.length);
