cat > /tmp/probe/diff.mjs <<'EOF'
// Differential runner: replays a corpus of argv arrays against both the Python
// executable and the Node port and reports byte-level divergences.
// Usage: node diff.mjs corpus.json [maxExamples] [concurrency]
import { spawn } from 'node:child_process';
import { readFileSync } from 'node:fs';

const EXE = '/workspace/dataset/test12_executable';
const NODE_ENTRY = '/output/test12.mjs';

// The two programs legitimately report different prog names in usage/error text
// (basename of argv[0], exactly as Python does), so normalise that one token.
const normalise = (text) =>
  text.split('test12_executable').join('%PROG%').split('test12.mjs').join('%PROG%');

function run(cmd, argv) {
  return new Promise((resolve) => {
    const child = spawn(cmd[0], [...cmd.slice(1), ...argv], { stdio: ['ignore', 'pipe', 'pipe'] });
    let out = '';
    let err = '';
    child.stdout.setEncoding('utf8');
    child.stderr.setEncoding('utf8');
    child.stdout.on('data', (chunk) => { out += chunk; });
    child.stderr.on('data', (chunk) => { err += chunk; });
    child.on('error', (error) => resolve({ out, err: `${err}<spawn error: ${error.message}>`, code: -1 }));
    child.on('close', (code) => resolve({ out, err, code }));
  });
}

const corpus = JSON.parse(readFileSync(process.argv[2], 'utf8'));
const maxExamples = Number(process.argv[3] ?? 8);
const concurrency = Number(process.argv[4] ?? 16);
const mismatches = [];

let next = 0;
async function worker() {
  for (;;) {
    const index = next;
    next += 1;
    if (index >= corpus.length) return;
    const argv = corpus[index];
    const [expected, actual] = await Promise.all([run([EXE], argv), run(['node', NODE_ENTRY], argv)]);
    const same =
      normalise(expected.out) === normalise(actual.out) &&
      normalise(expected.err) === normalise(actual.err) &&
      expected.code === actual.code;
    if (!same) mismatches.push({ index, argv, expected, actual });
  }
}

await Promise.all(Array.from({ length: concurrency }, worker));
mismatches.sort((left, right) => left.index - right.index);

console.log(`total=${corpus.length} mismatches=${mismatches.length}`);
for (const m of mismatches.slice(0, maxExamples)) {
  console.log(JSON.stringify(m));
}
